 function stopPlayback(){clearTimeout(audioWatchdogRef.current);audioWatchdogRef.current=null;clearTimeout(nextTimerRef.current);nextTimerRef.current=null;audioGenerationRef.current+=1;clipKeyRef.current='';if(audioRef.current){audioRef.current.pause();audioRef.current.onended=null;audioRef.current.onerror=null;audioRef.current.onplaying=null}if(typeof window!=='undefined'&&'speechSynthesis'in window)window.speechSynthesis.cancel()}
